// Parse trigger source and prepare workflow data
const items = $input.all();
const firstItem = items[0];

let triggerType = 'schedule';
let webhookData = null;
let callbackData = null;

// Check if this came from webhook (has body)
if (firstItem && firstItem.json && firstItem.json.body) {
  webhookData = firstItem.json.body;

  // Check if it's a callback (has action and digest_id)
  if (webhookData.action && webhookData.digest_id) {
    triggerType = 'callback';
    callbackData = {
      action: webhookData.action,
      digest_id: webhookData.digest_id,
      callback_query_id: webhookData.callback_query_id,
      chat_id: webhookData.chat_id,
      message_id: webhookData.message_id,
      edited_content: webhookData.edited_content || null
    };
  } 
  // Otherwise it's a manual trigger
  else if (webhookData.trigger === 'manual') {
    triggerType = 'manual';
  }
}

// Get today's date in consistent format (YYYY-MM-DD)
const today = new Date();
const todayDate = today.toISOString().split('T')[0];

// Get yesterday's date (for fetching articles from last 2 days)
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayDate = yesterday.toISOString().split('T')[0];

// Get Telegram Chat ID
// Priority: webhook data > hardcoded
const telegramChatId = (webhookData && webhookData.chat_id) 
  ? webhookData.chat_id 
  : '1925139795'; // ← SENIN TELEGRAM CHAT ID'N

// Prepare output
return {
  triggerType: triggerType,
  todayDate: todayDate,
  yesterdayDate: yesterdayDate,
  timestamp: new Date().toISOString(),
  webhookData: webhookData,
  callbackData: callbackData,
  telegramChatId: telegramChatId
};

// Group articles into a single array with scoring and sorting
// IMPORTANT: Generate correct website URLs (cemkoyluoglu.codes) NOT source URLs (nuvemmag.com)
const items = $input.all();
const SITE_BASE_URL = 'https://cemkoyluoglu.codes/tech-news';

// Define category weights for diversity (higher = more interesting)
const categoryWeights = {
  'AI': 1.2,
  'Cybersecurity': 1.15,
  'Cloud': 1.1,
  'Hardware': 1.1,
  'Data Science': 1.05,
  'Software': 1.0,
  'General': 0.9
};

// Define trusted sources (add more as needed)
const trustedSources = [
  'techcrunch.com',
  'theverge.com',
  'arstechnica.com',
  'wired.com',
  'mit.edu',
  'stanford.edu'
];

// Calculate score for each article
const articlesWithScores = items.map(item => {
  // Generate the correct article URL for our website
  const articleUrl = `${SITE_BASE_URL}/${item.json.slug}`;

  const article = {
    id: item.json.id,
    title: item.json.title,
    title_en: item.json.title_en,
    summary_en: item.json.summary_en,
    slug: item.json.slug,
    category: item.json.category,
    // CRITICAL: Use our website URL, NOT the source URL (nuvemmag.com)
    article_url: articleUrl,
    created_at: item.json.created_at
  };

  let score = 0;

  // 1. Novelty Score (0-30 points) - newer articles score higher
  const articleDate = new Date(article.created_at);
  const now = new Date();
  const hoursSincePublished = (now - articleDate) / (1000 * 60 * 60);
  const noveltyScore = Math.max(0, 30 - (hoursSincePublished * 1.5));
  score += noveltyScore;

  // 2. Category Diversity Score (0-20 points)
  const categoryWeight = categoryWeights[article.category] || 1.0;
  score += categoryWeight * 20;

  // 3. Source Credibility Score (0-25 points)
  // Note: We use the original source_url from the item for scoring, not article_url
  const originalSourceUrl = item.json.source_url || item.json.original_source || '';
  const isTrustedSource = trustedSources.some(trusted => originalSourceUrl.includes(trusted));
  score += isTrustedSource ? 25 : 10;

  // 4. Content Depth Score (0-25 points)
  const contentLength = (article.content_en || '').length;
  const summaryLength = (article.summary_en || '').length;
  const titleLength = (article.title_en || '').length;

  // Longer, more detailed content scores higher
  const depthScore = Math.min(25, (contentLength / 200) + (summaryLength / 50) + (titleLength / 10));
  score += depthScore;

  return {
    ...article,
    _score: Math.round(score * 100) / 100 // Round to 2 decimals
  };
});

// Sort by score in descending order (highest score first)
const sortedArticles = articlesWithScores.sort((a, b) => b._score - a._score);

// Remove the _score field before returning (optional, keep for debugging)
const articles = sortedArticles.map(({ _score, ...article }) => article);

return {
  articles: articles,
  articleCount: articles.length,
  todayDate: $('Parse Trigger Type').item.json.todayDate,
  // Include scoring info for debugging
  scoringInfo: {
    highestScore: sortedArticles[0]?._score || 0,
    lowestScore: sortedArticles[sortedArticles.length - 1]?._score || 0,
    averageScore: sortedArticles.reduce((sum, a) => sum + a._score, 0) / sortedArticles.length
  }
};

// Prepare Telegram message with inline buttons
const digest = $input.first().json;
const content = digest.suggested_content || 'No content generated';

// Telegram has 4096 char limit - show as much as possible
const maxLength = 3500; // Leave room for header and buttons
const displayContent = content.length > maxLength 
  ? content.substring(0, maxLength) + '\n\n⚠️ [Content truncated due to Telegram limit - full version will be posted to LinkedIn]'
  : content;

const message = `📰 *Daily LinkedIn Digest Ready!*\n\n📅 Date: ${digest.digest_date}\n📊 Articles: ${digest.article_count}\n\n${displayContent}\n\n✅ Choose an action:`;

// Inline keyboard - removed "View Full" button
const replyMarkup = {
  inline_keyboard: [
    [
      { text: '✅ Approve & Post', callback_data: `approve_${digest.id}` },
      { text: '❌ Reject', callback_data: `reject_${digest.id}` }
    ],
    [
      { text: '✏️ Edit & Approve', callback_data: `edit_${digest.id}` }
    ]
  ]
};

return {
  chatId: $('Parse Trigger Type').first().json.telegramChatId,
  text: message,
  replyMarkup: replyMarkup,
  digestId: digest.id,
  digestDate: digest.digest_date
};

