// Get the digest data from Fetch Digest by ID node
const digest = $('Fetch Digest by ID').first().json;

// Get edited_content if exists, otherwise use suggested_content
const content = digest.edited_content || digest.suggested_content;

// Check if content exists
if (!content) {
  throw new Error('No content found in digest');
}

// Remove markdown bold syntax (**text** → text)
const cleanContent = content.replace(/\*\*(.*?)\*\*/g, '$1');

// Return all data with clean_content added
return {
  json: {
    ...digest,
    clean_content: cleanContent
  }
};

// CRITICAL: Validate and enforce LinkedIn character limit
const MAX_LINKEDIN_CHARS = 3000;
const SAFE_LIMIT = 2800;
const TARGET_LIMIT = 2700;

const aiOutput = $input.first().json;
let content = aiOutput.message?.content || '';

// POST-PROCESSING: Remove any character count or meta info that AI might have added
// Patterns like: (Characters: 1,005), [1234 characters], (1234 chars), etc.
content = content
  .replace(/\(Characters?:\s*[\d,]+\)/gi, '')
  .replace(/\[\d+[\s,]*characters?\]/gi, '')
  .replace(/\(\d+[\s,]*chars?\)/gi, '')
  .replace(/Character count:\s*\d+/gi, '')
  .replace(/Total:\s*\d+\s*characters?/gi, '')
  .replace(/---[\s\S]*$/gm, '') // Remove any trailing notes after ---
  .replace(/\n{3,}/g, '\n\n') // Clean up excessive newlines
  .trim();

const originalCharCount = content.length;

let validationStatus = 'valid';
let validationMessage = '';
let finalContent = content;

// If over hard limit, we need to truncate smartly
if (originalCharCount > MAX_LINKEDIN_CHARS) {
  validationStatus = 'exceeded_hard_limit';

  // Smart truncation: remove last article
  let truncated = content;

  // Find and remove the last article (starts with emoji before last hashtags)
  const hashtagIndex = truncated.lastIndexOf('#');
  if (hashtagIndex > 0) {
    // Find the start of hashtags section
    let hashtagStart = truncated.lastIndexOf('\n\n#');
    if (hashtagStart === -1) hashtagStart = truncated.lastIndexOf('\n#');

    // Get content before hashtags and hashtags separately
    const mainContent = hashtagStart > 0 ? truncated.substring(0, hashtagStart) : truncated;
    const hashtags = hashtagStart > 0 ? truncated.substring(hashtagStart) : '';

    // Find last article link
    const lastLinkIndex = mainContent.lastIndexOf('🔗 https://');
    if (lastLinkIndex > 0) {
      // Find the emoji that starts this article (go back to find newline + emoji)
      let articleStart = mainContent.lastIndexOf('\n\n', lastLinkIndex - 5);
      if (articleStart > 0) {
        truncated = mainContent.substring(0, articleStart) + hashtags;
      }
    }
  }

  // If still too long, hard cut
  if (truncated.length > SAFE_LIMIT) {
    const cutPoint = truncated.lastIndexOf('\n\n', SAFE_LIMIT);
    if (cutPoint > SAFE_LIMIT - 500) {
      truncated = truncated.substring(0, cutPoint);
    } else {
      truncated = truncated.substring(0, SAFE_LIMIT);
    }
    // Add hashtags back if missing
    if (!truncated.includes('#')) {
      truncated += '\n\n#AI #Tech #Innovation';
    }
  }

  finalContent = truncated;
  validationMessage = `⚠️ Content exceeded ${MAX_LINKEDIN_CHARS} chars (${originalCharCount}). Auto-trimmed to ${finalContent.length} chars.`;

} else if (originalCharCount > SAFE_LIMIT) {
  validationStatus = 'warning';
  validationMessage = `⚠️ Content is ${originalCharCount} chars (close to ${MAX_LINKEDIN_CHARS} limit).`;

} else {
  validationStatus = 'valid';
  validationMessage = `✅ Content validated: ${originalCharCount} chars (under ${SAFE_LIMIT} safe limit).`;
}

console.log(`Character validation: ${validationStatus} - Original: ${originalCharCount}, Final: ${finalContent.length}`);

return {
  message: {
    content: finalContent
  },
  validation: {
    status: validationStatus,
    originalCharCount: originalCharCount,
    finalCharCount: finalContent.length,
    message: validationMessage,
    wasTruncated: originalCharCount !== finalContent.length,
    linkedinLimit: MAX_LINKEDIN_CHARS,
    safeLimit: SAFE_LIMIT
  }
};
